<script setup lang="ts">
import { useI18n } from 'vue-i18n'
import type { Channel, Delivery } from '../types'
import Card from './Card.vue'
const { locale, t } = useI18n()
const { channels, deliveries, channelType, deliveryStatus, openChannel, testSaved, deleteChannel } = defineProps<{ channels: Channel[], deliveries: Delivery[], channelType: (value: string) => string, deliveryStatus: (value: string) => string, openChannel: (channel?: Channel) => void, testSaved: (id: string) => void, deleteChannel: (id: string) => void }>()
</script>
<template>
<div class="section-head"><div><h2>{{t("通知通道")}}</h2><p>{{t("支持邮件、钉钉、飞书、企业微信、Slack、Telegram 和 Webhook。")}}</p></div><button class="primary" @click="openChannel()">{{t("＋ 添加通道")}}</button></div><div class="channel-grid"><Card v-for="c in channels" :key="c.id" as="article" class="channel-card"><div class="channel-top"><span class="channel-icon">{{c.type==='email'?'✉':c.type==='dingtalk'?t("钉"):c.type==='feishu'?t("飞"):c.type==='wecom'?t("企"):'↗'}}</span><span class="badge" :class="c.enabled?'online':'offline'">{{c.enabled?t("启用"):t("停用")}}</span></div><h3>{{c.name}}</h3><small>{{channelType(c.type)}}</small><div class="channel-actions"><button @click="openChannel(c)">{{t("编辑")}}</button><button @click="testSaved(c.id)">{{t("测试")}}</button><button class="danger" @click="deleteChannel(c.id)">{{t("删除")}}</button></div></Card><Card v-if="!channels.length" class="panel empty">{{t("尚未配置通知通道。添加通道后，在告警规则中选择接收人。")}}</Card></div><div class="section-head"><div><h2>{{t("通知投递记录")}}</h2><p>{{t("最近通知的投递结果。")}}</p></div></div><Card class="panel"><div class="table-wrap"><table><thead><tr><th>{{t("通道")}}</th><th>{{t("类型")}}</th><th>{{t("状态")}}</th><th>{{t("尝试次数")}}</th><th>{{t("时间")}}</th><th>{{t("错误")}}</th></tr></thead><tbody><tr v-for="d in deliveries.slice(0,30)" :key="d.id"><td>{{d.channel_name}}</td><td>{{channelType(d.channel_type)}}</td><td>{{deliveryStatus(d.status)}}</td><td>{{d.attempts}}</td><td>{{new Date(d.created_at).toLocaleString(locale)}}</td><td>{{d.error||'—'}}</td></tr><tr v-if="!deliveries.length"><td colspan="6" class="empty">{{t("暂无投递记录")}}</td></tr></tbody></table></div></Card>
</template>
